for _,kind in ipairs({'reef','braille','cavern','crater','marine'})do
 local list={};layouts[kind]=list;local ordinal=0
 local function card(part,w,x,y,z,h,extra)
  local b=bounds[kind][part];local start=3.12+ordinal*.032;ordinal=ordinal+1
  local d={texture='undersea-'..kind..'-kit.png',imageWidth=1536,imageHeight=1024,cutout=true,
   points={{b[1],b[2]},{b[3],b[2]},{b[3],b[4]},{b[1],b[4]}},width=w,x=x,y=y,z=z,
   heightScale=h/((b[4]-b[2])*w*30/(b[3]-b[1])),begin=start,duration=.8,
   direction=z>1 and-1 or 1,foldOffset=math.min(.06,(start-3.12)*.10)}
  for k,v in pairs(extra or{})do d[k]=v end
  if part==8 and(kind=='reef'or kind=='braille')then
   local cutX=kind=='reef'and 1310 or 1275
   local cutY=kind=='reef'and 657 or 660
   d.points={{b[1],b[2]},{b[3],b[2]},{b[3],cutY},{cutX,cutY},{cutX,b[4]},{b[1],b[4]}}
   if d.mirror then for _,p in ipairs(d.points)do p[1]=b[1]+b[3]-p[1]end end
  end
  list[#list+1]=d
  return d
 end
 card(2,3.00,0,-22,-2.89,134)
 card(1,2.02,-1.98,-20,-2.47,125)
 card(3,2.11,1.92,-20,-2.22,115)
 card(4,1.01,-2.60,-27,-1.39,95,{sway=.010})
 card(4,.85,2.66,-25,-1.21,85,{sway=.014,mirror=true})
 if kind=='cavern'then
  card(7,2.46,0,111,-3.28,40,{mount='lid'})
 elseif fishShapes[kind]then
  local b=bounds[kind][7];local w,h=2.30,34
  local sx=w*30/(b[3]-b[1]);local sy=h/(b[4]-b[2])
  local startOrdinal=ordinal
  for i,points in ipairs(fishShapes[kind])do
   local x0,y0,x1,y1=math.huge,math.huge,-math.huge,-math.huge
   for _,p in ipairs(points)do x0=math.min(x0,p[1]);y0=math.min(y0,p[2]);x1=math.max(x1,p[1]);y1=math.max(y1,p[2])end
   local d=card(7,(x1-x0)*sx/30,-.50+((x0+x1-b[1]-b[3])/2)*sx/30,
    111+(b[4]-y1)*sy,-3.10,(y1-y0)*sy,
    {mount='lid',hangingFractions={.5},eventMotion='underseaFish',eventIndex=i,underseaHabitat=kind=='reef'and'underwater:'or'underwater:'..kind,
     swimDirection=kind=='crater'and 1 or -1,floatY=.35,floatPhase=i*.71,underseaDetail=true,doubleSidedArt=true})
   d.points=points;d.heightScale=sy/sx;d.begin=3.30;d.foldOffset=.018
  end
  ordinal=startOrdinal+1
 else
  card(7,1.70,-.72,123,-3.28,27,{mount='lid',driftX=4,floatY=.9})
 end
 card(8,1.75,1.20,95,-3.25,34,{mount='lid',driftX=2.2,floatY=1.2,mutedWater=true})
 card(8,1.70,-1.10,83,-3.18,25,{mount='lid',driftX=1.4,floatY=1,mutedWater=true,mirror=true})
 card(10,1.70,-1.55,-36,-1.46,44)
 card(10,1.53,1.62,-35,-1.40,40,{mirror=true})
 card(5,1.10,-2.43,-24,1.12,36)
 card(6,1.10,2.43,-24,1.14,35,{sway=.006})
 card(12,.80,-2.04,-27,2.10,42,{sway=.010})
 card(12,.74,2.09,-26,2.08,39,{sway=.013,mirror=true})
 card(11,.77,-1.03,-22,2.73,27)
 card(11,.71,1.07,-21,2.75,25,{mirror=true})
 -- Rock columns begin on the basin floor; their caps rise above the water.
